(function(global){
 'use strict';
 var LABEL={all:'全部',research:'研究成果',policy:'项目与政策',community:'学界资讯',conference:'会议征稿'};
 function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
 function cleanTitle(s){return String(s||'').replace(/\s*(?:本网讯|本报讯)[\s\S]*$/,'').replace(/\s*时间[：:][\s\S]*?(?=\s*地点[：:]|$)/g,'').replace(/\s*地点[：:][\s\S]*$/,'').replace(/\s+/g,' ').trim();}
 function safeURL(s){try{var u=new URL(s);return /^https?:$/.test(u.protocol)?u.href:'';}catch(e){return '';}}
 function keyURL(s){var u=new URL(s);u.hash='';['utm_source','utm_medium','utm_campaign','from','spm'].forEach(function(k){u.searchParams.delete(k);});return u.href.replace(/^https?:\/\//,'').replace(/\/$/,'');}
 function category(it,kind){var t=cleanTitle(it.title);if(/申报|立项|课题|科研项目|基金|政策|管理办法|入选公示/.test(t)||it.type==='project')return 'policy';if(!/赴.*参加|相关情况|成功举办|在.*举行|在.*举办/.test(t)&&(/征文|征稿|参会|会议通知|学术.*通知|论坛.*预告|活动预告/.test(t)||it.type==='conference'))return 'conference';if(kind==='papers'||it.cat==='期刊'||it.type==='paper'||it.type==='journal')return 'research';return 'community';}
 function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
 function normalize(sources){var out=[],urls=new Map(),titles=new Map();sources.forEach(function(src){(src.data.items||src.data||[]).forEach(function(it){var title=cleanTitle(it.title),url=safeURL(it.link);if(!title||title.length<6||!url||/^(首页|更多|通知公告|期刊新闻|网站地图|无标题)$/.test(title))return;var tk=title.toLowerCase().replace(/[\s\p{P}\p{S}]/gu,''),uk=keyURL(url);if(urls.has(uk)||titles.has(tk))return;var d=String(it.date||'').match(/^\d{4}-\d{2}(?:-\d{2})?/);var date=d?d[0].replace(/-00$/,''):'';var row={title:title,translation:it.titleZh||'',url:url,source:it.journalZh||it.journal||it.org||it.source||'原文来源',date:date,category:category(it,src.kind),kind:src.kind};urls.set(uk,row);titles.set(tk,row);out.push(row);});});var now=today();out.sort(function(a,b){var af=a.date>now,bf=b.date>now;if(af!==bf)return af?1:-1;return b.date.localeCompare(a.date);});return out;}
 function filtered(rows,state){return rows.filter(function(r){return (state.cat==='all'||r.category===state.cat)&&(!state.q||(r.title+' '+r.translation+' '+r.source).toLowerCase().includes(state.q.toLowerCase()))&&(!state.from||!!r.date&&r.date>=state.from.slice(0,r.date.length))&&(!state.to||!!r.date&&r.date<=state.to.slice(0,r.date.length));});}
 var api={normalize:normalize,filter:filtered,cleanTitle:cleanTitle,category:category};
 if(typeof module==='object'&&module.exports){module.exports=api;return;}
 var data=[],stamp='',failed=[],states={home:{cat:'all',q:'',from:'',to:'',limit:6},page:{cat:'all',q:'',from:'',to:'',limit:20}};
 function tabs(scope){return '<div class="af-tabs" role="group" aria-label="动态分类">'+Object.keys(LABEL).map(function(k){return '<button type="button" data-af-cat="'+k+'" aria-pressed="'+(states[scope].cat===k)+'">'+LABEL[k]+'</button>';}).join('')+'</div>';}
 function row(r,lead){var date=r.date?((r.date>today()?(r.kind==='papers'?'刊期：':'预告日期：'):'来源日期：')+r.date):'日期未标注';return '<article class="af-item'+(lead?' af-lead':'')+'"><p class="af-meta"><span>'+LABEL[r.category]+'</span><span>'+esc(r.source)+'</span><span>'+esc(date)+'</span></p><h3><a href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer">'+esc(r.title)+'</a></h3>'+(r.translation?'<p class="af-translation">'+esc(r.translation)+'</p>':'')+'</article>';}
 function status(){return (stamp?'数据更新：'+esc(stamp):'数据更新时间未标注')+(failed.length?' · 部分来源暂不可用':'');}
 function paint(scope){var root=document.getElementById(scope==='home'?'homeNews':'academicFeedPage');if(!root)return;var state=states[scope],rows=filtered(data,state);root.querySelector('[data-af-tabs]').innerHTML=tabs(scope);var list=root.querySelector('[data-af-list]');list.classList.toggle('af-home-grid',scope==='home'&&rows.length>1);list.innerHTML=rows.length?rows.slice(0,state.limit).map(function(r,i){return row(r,scope==='home'&&i===0);}).join(''):'<p class="af-empty">'+(failed.length===3?'动态暂时加载失败，请重试。':'没有符合条件的动态。试试其他分类或清除筛选。')+'</p>';root.querySelector('[data-af-status]').textContent=(stamp?'数据更新：'+stamp:'数据更新时间未标注')+(failed.length?' · 部分来源暂不可用':'');var count=root.querySelector('[data-af-count]');if(count)count.textContent='共 '+rows.length+' 条，已显示 '+Math.min(rows.length,state.limit)+' 条';var more=root.querySelector('[data-af-more]');if(more)more.hidden=rows.length<=state.limit;}
 function openPage(cat){states.page.cat=cat||'all';states.page.limit=20;if(typeof global.spNavigate==='function')global.spNavigate('academicnews');else if(typeof global.go==='function')global.go('academicnews');paint('page');}
 function bind(root,scope){root.addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-af-cat')){states[scope].cat=b.getAttribute('data-af-cat');states[scope].limit=scope==='home'?6:20;paint(scope);}if(b.hasAttribute('data-af-open'))openPage(states.home.cat);if(b.hasAttribute('data-af-more')){states.page.limit+=20;paint('page');}if(b.hasAttribute('data-af-reset')){states[scope]={cat:'all',q:'',from:'',to:'',limit:20};root.querySelectorAll('input').forEach(function(x){x.value='';});paint(scope);}if(b.hasAttribute('data-af-retry'))load();});root.addEventListener('input',function(e){var k=e.target.getAttribute('data-af-field');if(k){states[scope][k]=e.target.value;states[scope].limit=20;paint(scope);}});}
 function mount(){var grid=document.querySelector('#sportsPortal .sp-grid');if(grid&&!document.getElementById('homeNews')){var home=document.createElement('section');home.id='homeNews';home.className='af af-home';home.setAttribute('aria-labelledby','academicFeedTitle');home.innerHTML='<header class="af-heading"><div><h2 id="academicFeedTitle">学术动态</h2><p>研究成果、项目政策与学界资讯</p></div><button type="button" data-af-open>查看全部 →</button></header><div data-af-tabs></div><p class="af-status" data-af-status role="status">正在加载动态…</p><div data-af-list><p class="af-empty">正在加载动态…</p></div>';grid.parentNode.insertBefore(home,grid);bind(home,'home');}
 var page=document.getElementById('vw-academicnews');if(page&&!document.getElementById('academicFeedPage')){page.innerHTML='<div id="academicFeedPage" class="af af-page"><header class="af-heading"><div><h1>学术动态</h1><p>按内容找消息，按日期追踪变化。</p></div><a href="#confcal">会议日历 →</a></header><div data-af-tabs></div><div class="af-controls"><label class="af-search">搜索标题或来源<input type="search" data-af-field="q" placeholder="搜索论文、院校、项目…"></label><label>来源日期起<input type="date" data-af-field="from"></label><label>来源日期止<input type="date" data-af-field="to"></label><button type="button" data-af-reset>清除筛选</button></div><div class="af-info"><p class="af-status" data-af-status role="status">正在加载动态…</p><span data-af-count></span><button type="button" data-af-retry>重新加载</button></div><p class="af-note">来源日期沿用原始记录；论文可能标注刊期，未来日期单独标为预告或刊期。数据更新时间不代表消息发布时间。</p><div data-af-list aria-live="polite"><p class="af-empty">正在加载动态…</p></div><button class="af-more" type="button" data-af-more hidden>加载更多</button></div>';bind(document.getElementById('academicFeedPage'),'page');}}
 function load(){failed=[];return Promise.all([{file:'news-snapshot.json',kind:'papers'},{file:'xuejie-snapshot.json',kind:'circle'},{file:'daily-dynamics.json',kind:'daily'}].map(function(src){return fetch(src.file,{cache:'no-store'}).then(function(r){if(!r.ok)throw Error('http');return r.json();}).then(function(d){if(!Array.isArray(d)&&!Array.isArray(d.items))throw Error('schema');return {kind:src.kind,data:d};}).catch(function(){failed.push(src.file);return {kind:src.kind,data:{items:[]}};});})).then(function(sources){data=normalize(sources);stamp=sources.map(function(s){return String(s.data.generatedAt||'').slice(0,10);}).filter(Boolean).sort().reverse()[0]||'';paint('home');paint('page');});}
 function legacy(){var h=location.hash;if(/^#daily(?:\/|$)/.test(h)){states.page.cat=h.includes('journal')?'research':h.includes('univ')?'community':'all';history.replaceState(null,'',location.pathname+location.search+'#academicnews');if(typeof global.go==='function')global.go('academicnews');paint('page');}}
 function init(){mount();global.renderAcademicNews=function(){paint('page');};global.renderAcademicNews.__spNewsPatched=true;var oldGo=global.go;if(typeof oldGo==='function'){global.go=function(route){if(route==='daily'){route='academicnews';states.page.cat='all';}return oldGo.apply(this,[route].concat(Array.prototype.slice.call(arguments,1)));};}global.setAcademicNewsFilter=function(cat){states.page.cat={paper:'research',project:'policy',event:'conference',journal:'research'}[cat]||cat||'all';paint('page');};legacy();global.addEventListener('hashchange',legacy);load();}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})(typeof window==='undefined'?globalThis:window);
